from __future__ import annotations

from datetime import datetime, timedelta, timezone

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus
from tests.conftest import NOW, make_task


# ── Tag ──────────────────────────────────────────────────────────────

class TestTag:
    def test_normalizes_to_lowercase_stripped(self):
        tag = Tag("  Hello  ")
        assert tag.name == "hello"

    def test_allows_alphanumeric_hyphen_underscore(self):
        tag = Tag("my-tag_2")
        assert tag.name == "my-tag_2"

    @pytest.mark.parametrize("bad_name", ["", "   ", "  \t "])
    def test_empty_name_raises(self, bad_name):
        with pytest.raises(ValueError, match="must not be empty"):
            Tag(bad_name)

    def test_name_too_long_raises(self):
        with pytest.raises(ValueError, match="32 characters"):
            Tag("a" * 33)

    def test_name_exactly_32_ok(self):
        tag = Tag("a" * 32)
        assert len(tag.name) == 32

    @pytest.mark.parametrize("bad_char", ["hello world", "tag!", "tag@name"])
    def test_illegal_characters_raise(self, bad_char):
        with pytest.raises(ValueError, match="illegal character"):
