from __future__ import annotations

from datetime import timedelta

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus
from tasks_api.queries import TaskPage, TaskQuery, TaskQueryError, apply_query
from tests.conftest import NOW, make_task


# ── TaskQuery validation ─────────────────────────────────────────────

class TestTaskQueryValidation:
    def test_defaults(self):
        q = TaskQuery()
        assert q.sort == "created_at"
        assert q.limit == 20
        assert q.offset == 0
        assert q.descending is False

    @pytest.mark.parametrize("bad_sort", ["id", "bogus", ""])
    def test_invalid_sort_raises(self, bad_sort):
        with pytest.raises(TaskQueryError, match="sort must be one of"):
            TaskQuery(sort=bad_sort)

    @pytest.mark.parametrize("bad_limit", [0, -1, 101])
    def test_invalid_limit_raises(self, bad_limit):
        with pytest.raises(TaskQueryError, match="limit"):
            TaskQuery(limit=bad_limit)

    def test_negative_offset_raises(self):
        with pytest.raises(TaskQueryError, match="offset"):
            TaskQuery(offset=-1)

    def test_tag_is_normalized(self):
        q = TaskQuery(tag="  MyTag  ")
        assert q.tag == "mytag"

    def test_invalid_tag_raises(self):
        with pytest.raises(ValueError):
            TaskQuery(tag="bad tag!")

    def test_blank_search_becomes_none(self):
        q = TaskQuery(search="   ")
        assert q.search is None

    def test_search_is_stripped(self):
        q = TaskQuery(search="  hello  ")
        assert q.search == "hello"

    @pytest.mark.parametrize("sort", ["created_at", "due_at", "priority", "title"])
    def test_valid_sort_fields_accepted(self, sort):
        q = TaskQuery(sort=sort)
        assert q.sort == sort


# ── TaskPage.has_more ────────────────────────────────────────────────

class TestTaskPage:
    def test_has_more_true(self):
        page = TaskPage(items=[make_task(id=i) for i in range(5)], total=10, limit=5, offset=0)
        assert page.has_more is True

    def test_has_more_false_at_end(self):
        page = TaskPage(items=[make_task(id=i) for i in range(5)], total=5, limit=5, offset=0)
        assert page.has_more is False

    def test_has_more_with_offset(self):
        page = TaskPage(items=[make_task(id=1)], total=6, limit=5, offset=5)
        assert page.has_more is False


# ── apply_query: filtering ───────────────────────────────────────────

class TestApplyQueryFiltering:
    @pytest.fixture
    def sample_tasks(self):
        past = NOW - timedelta(days=1)
        future = NOW + timedelta(days=1)
        return [
            make_task(id=1, title="Buy groceries", status=TaskStatus.PENDING, tags=[Tag("shopping")], due_at=past),
            make_task(id=2, title="Write report", status=TaskStatus.DONE, tags=[Tag("work")]),
            make_task(id=3, title="Read book", status=TaskStatus.PENDING, tags=[Tag("personal")], due_at=future),
            make_task(id=4, title="Buy supplies", status=TaskStatus.PENDING, tags=[Tag("shopping"), Tag("work")]),
        ]

    def test_no_filters_returns_all(self, sample_tasks):
        page = apply_query(sample_tasks, TaskQuery(), NOW)
        assert page.total == 4

    def test_filter_by_status(self, sample_tasks):
        page = apply_query(sample_tasks, TaskQuery(status=TaskStatus.DONE), NOW)
        assert page.total == 1
        assert page.items[0].id == 2

    def test_filter_by_tag(self, sample_tasks):
        page = apply_query(sample_tasks, TaskQuery(tag="shopping"), NOW)
        assert page.total == 2
        assert {t.id for t in page.items} == {1, 4}

    def test_filter_by_search(self, sample_tasks):
        page = apply_query(sample_tasks, TaskQuery(search="buy"), NOW)
        assert page.total == 2
        assert {t.id for t in page.items} == {1, 4}

    def test_search_case_insensitive(self, sample_tasks):
        page = apply_query(sample_tasks, TaskQuery(search="REPORT"), NOW)
        assert page.total == 1
        assert page.items[0].id == 2

    def test_filter_overdue_true(self, sample_tasks):
        page = apply_query(sample_tasks, TaskQuery(overdue=True), NOW)
        assert page.total == 1
        assert page.items[0].id == 1

    def test_filter_overdue_false(self, sample_tasks):
        page = apply_query(sample_tasks, TaskQuery(overdue=False), NOW)
        # Tasks 2 (done), 3 (future due), 4 (no due_at) are not overdue
        assert page.total == 3

    def test_combined_filters(self, sample_tasks):
        page = apply_query(
            sample_tasks,
            TaskQuery(status=TaskStatus.PENDING, tag="shopping"),
            NOW,
        )
        assert page.total == 2
        assert {t.id for t in page.items} == {1, 4}


# ── apply_query: sorting ────────────────────────────────────────────

class TestApplyQuerySorting:
    def test_sort_by_title(self):
        tasks = [make_task(id=1, title="Zebra"), make_task(id=2, title="Apple")]
        page = apply_query(tasks, TaskQuery(sort="title"), NOW)
        assert [t.id for t in page.items] == [2, 1]

    def test_sort_by_title_descending(self):
        tasks = [make_task(id=1, title="Apple"), make_task(id=2, title="Zebra")]
        page = apply_query(tasks, TaskQuery(sort="title", descending=True), NOW)
        assert [t.id for t in page.items] == [2, 1]

    def test_sort_by_priority(self):
        tasks = [
            make_task(id=1, priority=TaskPriority.LOW),
            make_task(id=2, priority=TaskPriority.HIGH),
            make_task(id=3, priority=TaskPriority.MEDIUM),
        ]
        page = apply_query(tasks, TaskQuery(sort="priority"), NOW)
        assert [t.id for t in page.items] == [2, 3, 1]

    def test_sort_by_due_at_none_last(self):
        tasks = [
            make_task(id=1, due_at=None),
            make_task(id=2, due_at=NOW + timedelta(days=1)),
            make_task(id=3, due_at=NOW - timedelta(days=1)),
        ]
        page = apply_query(tasks, TaskQuery(sort="due_at"), NOW)
        assert [t.id for t in page.items] == [3, 2, 1]

    def test_sort_by_created_at(self):
        tasks = [
            make_task(id=1, created_at=NOW + timedelta(hours=1)),
            make_task(id=2, created_at=NOW - timedelta(hours=1)),
        ]
        page = apply_query(tasks, TaskQuery(sort="created_at"), NOW)
        assert [t.id for t in page.items] == [2, 1]


# ── apply_query: pagination ─────────────────────────────────────────

class TestApplyQueryPagination:
    @pytest.fixture
    def many_tasks(self):
        return [make_task(id=i, title=f"Task {i}", created_at=NOW + timedelta(minutes=i)) for i in range(1, 11)]

    def test_limit(self, many_tasks):
        page = apply_query(many_tasks, TaskQuery(limit=3), NOW)
        assert len(page.items) == 3
        assert page.total == 10
        assert page.has_more is True

    def test_offset(self, many_tasks):
        page = apply_query(many_tasks, TaskQuery(limit=3, offset=8), NOW)
        assert len(page.items) == 2
        assert page.has_more is False

    def test_offset_beyond_total(self, many_tasks):
        page = apply_query(many_tasks, TaskQuery(offset=100), NOW)
        assert len(page.items) == 0
        assert page.total == 10
        assert page.has_more is False

    def test_empty_list(self):
        page = apply_query([], TaskQuery(), NOW)
        assert page.items == []
        assert page.total == 0
        assert page.has_more is False

